def evaluate_return_policy(item, item_category, policy, delivery_days_ago):
    # Policy rules

    if item_category in policy['final_sale_categories']:
        return {
            "reason": f"{item} in these categories are final sale and can't be returned: {policy['final_sale_categories']}",
            "decision": "deny"
        }
    else:
        item_price = item['price']
        total_price = item_price
        fee = total_price * 0.18
        refund = total_price - fee
        return {
            "reason": f"{policy}",
            "decision": "return",
            "fee_percent": 0.18,
            "refund": refund
        }

# Example usage
policy = {
    "final_sale_categories": [" compasses and headlamps"]
}
item = {"name": "Ridgeline 2-person tent", "price": 50, "category": "tents"}
delivery_days_ago = 43

result = evaluate_return_policy(item, item['category'], policy, delivery_days_ago)
